ndefined) {\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.applyStaffId.name\").setValue(inspectInitData.applyStaffId);\n\t}\n\t//请检部门\n\tif (inspectInitData.applyDeptId !== undefined) {\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.applyDeptId.name\").setValue(inspectInitData.applyDeptId);\n\t}\n\t//请检时间\n\tif (inspectInitData.applyTime !== undefined) {\n\t\tReactAPI.getComponentAPI(\"DatePicker\").APIs(\"inspect.applyTime\").setValue(new Date(inspectInitData.applyTime));\n\t}\n\t//业务类型\n\tif (inspectInitData.busiType !== undefined) {\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.busiTypeId.name\").setValue(inspectInitData.busiType);\n\t}\n\t//备注\n\tif (inspectInitData.memo !== undefined) {\n\t\tReactAPI.getComponentAPI(\"TextArea\").APIs(\"inspect.memoField\").setValue(inspectInitData.memo);\n\t}\n\n\t//批号\n\tif (inspectInitData.batchCode !== undefined) {\n\t\tsetTimeout(function () {\n\t\t\tReactAPI.getComponentAPI(\"Input\").APIs(\"inspect.batchCode\").setValue(inspectInitData.batchCode);\n\t\t}, 400);\n\t}\n\t//需实验室检验，不传取默认值\n\tif (inspectInitData.needLabCheck !== undefined) {\n\t\tReactAPI.getComponentAPI(\"Checkbox\").APIs(\"inspect.needLab\").setValue(inspectInitData.needLabCheck);\n\t}\n\t//采样点\n\tif (inspectInitData.psId !== undefined) {\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.psId.name\").setValue(inspectInitData.psId);\n\t}\n\t//供应商\n\tif (inspectInitData.vendorId !== undefined) {\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.vendorId.name\").setValue(inspectInitData.vendorId);\n\t}\n\tdebugger;\n\t//物料ID\n\tif (inspectInitData.prodId !== undefined) {\n\t\tReactAPI.getComponentAPI(\"Reference\").APIs(\"inspect.prodId.code\").setValue(inspectInitData.prodId);\n\t\tvar productObj = inspectInitData.prodId;\n\t\tsetTimeout(function () {\n\t\t\tproductObj.isBatch = {\n\t\t\t\tid: ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"inspect.prodId.isBatch\").getValue().value\n\t\t\t};\n\t\t\