\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"foundation.data.cross.company\", differentCompanyMsg.substring(1)));\n\t\treturn false;\n\t}\n\tconsole.log(testPlanArr);\n\tif (testPlanArr.length === 0) {\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"QCS.custom.random1624424081281\"));\n\t\treturn false;\n\t}\n\n\tReactAPI.createDialog(\"countNumEditDialog\", {\n\t\ttitle: ReactAPI.international.getText(\"LIMSBasic.viewtitle.randon1615774477306\"),\n\t\turl: \"/msService/LIMSBasic/materialTestPlan/matTestPlan/countNumEdit\",\n\t\tisRef: false, // 是否开启参照\n\t\twidth: ''350px'',\n\t\theight: ''200px'',\n\t\tbuttons: [{ //保存\n\t\t\ttext: ReactAPI.international.getText(\"Button.text.save\"),\n\t\t\ttype: \"primary\",\n\t\t\tonClick: function onClick(event) {\n\t\t\t\tvar testPlanIds = testPlanArr.toString();\n\t\t\t\tvar countNum = event.ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"matTestPlan.countNum\").getValue();\n\n\t\t\t\tvar regx = /^\\d+$/;\n\t\t\t\tif (!regx.test(countNum)) {\n\t\t\t\t\tevent.ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"matTestPlan.countNum\").setValidateStyle(''error'', ReactAPI.international.getText(''LIMSBasic.custom.countNumberRangeError'', event.ReactAPI.getComponentAPI(\"Label\").APIs(\"matTestPlan.countNum\").getValue(), \"0\"));\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\n\t\t\t\t$.ajax({\n\t\t\t\t\ttype: \"post\",\n\t\t\t\t\turl: \"/msService/QCS/testPlan/inspectPlan/updatePlanCountNum\",\n\t\t\t\t\tasync: false,\n\t\t\t\t\tdata: {\n\t\t\t\t\t\t\"ids\": testPlanIds,\n\t\t\t\t\t\t\"countNum\": countNum\n\t\t\t\t\t},\n\t\t\t\t\tsuccess: function success(result) {\n\t\t\t\t\t\tReactAPI.destroyDialog(\"countNumEditDialog\");\n\t\t\t\t\t\tsetTimeout(function () {\n\t\t\t\t\t\t\ttestPlanDg.refreshDataByRequst();\n\t\t\t\t\t\t\tReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"EditView.notice.operate.success\"));\n\t\t\t\t\t\t}, 200);\n\t\t\t\t\t},\n\t\t\t\t\terror: function error(result) {\n\t\